package com.rpis.backend.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.List;

/**
 * A table of the Terminal Report (for example "Table 1. Production and market indicators
 * during the ASF outbreak period" of the official format).
 *
 * <p>The proponent enters the caption and the cells; the table number is generated by the
 * document renderer from the order of the tables (body tables 1, 2, 3 ..., appendix tables
 * A1, A2, ...), so no number is stored and none is invented.</p>
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class TerminalReportTable {

    private String caption;

    /** Optional note printed under the table. */
    private String note;

    /** Column headings, in order. */
    private List<String> columns = new ArrayList<>();

    /** Rows; every row holds one cell per column. */
    private List<List<String>> rows = new ArrayList<>();

    /** True when the table has a caption or at least one cell with content. */
    public boolean hasContent() {
        if (caption != null && !caption.isBlank()) {
            return true;
        }
        if (rows != null) {
            for (List<String> row : rows) {
                if (row != null) {
                    for (String cell : row) {
                        if (cell != null && !cell.isBlank()) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
}
